public class DashboardProvider : IDashboardProvider
{
    private readonly IDashboardService _service;

    public async Task<IReadOnlyList<DashboardWidget>> GetWidgetsAsync(
        string dashboardId, CancellationToken ct = default)
    {
        return await _service.GetWidgetsAsync(dashboardId, ct);
    }

    public async Task<bool> SaveLayoutAsync(string dashboardId, 
        IEnumerable<DashboardWidget> widgets, CancellationToken ct = default)
    {
        return await _service.SaveLayoutAsync(dashboardId, widgets, ct);
    }

    public async Task<IReadOnlyList<WidgetTypeDefinition>> GetAvailableWidgetTypesAsync(
        CancellationToken ct = default)
    {
        return await _service.GetWidgetTypesAsync(ct);
    }
}
